@register.simple_tag
def service_icon_path(service_name: str) -> str:
    """
    Returns the SVG path string for a service name by keyword matching.
    Falls back to a sparkles icon when no keyword matches.
    Matching is case-insensitive and uses substring search so
    e.g. 'Deep Tissue Massage' matches 'massage'.
    """
    name_lower = service_name.lower()
    for keyword, path in ICON_MAP.items():
        if keyword in name_lower:
            return path
    return DEFAULT_ICON